class Solution:
    def subarrayLCM(self, nums: List[int], k: int) -> int:
        from math import gcd
        n = len(nums)
        ans = 0
        for i in range(n):
            cur = 1
            for j in range(i, n):
                cur = cur // gcd(cur, nums[j]) * nums[j]
                if k % cur:
                    break
                if cur == k:
                    ans += 1
        return ans

