class Solution {
public:
    int subarrayLCM(vector<int>& nums, int k) {
        int n = nums.size(), ans = 0;
        for (int i = 0; i < n; i++) {
            vector<pair<int,long long>> vals;
            for (int j = i; j < n; j++) {
                int x = nums[j];
                if (k % x) break;
                map<int,long long> nxt;
                nxt[x] += 1;
                for (auto& [v, c] : vals) {
                    int nv = v / __gcd(v, x) * x;
                    if (k % nv == 0) nxt[nv] += c;
                }
                vals.assign(nxt.begin(), nxt.end());
                for (auto& [v, c] : vals) if (v == k) ans += c;
            }
        }
        return ans;
    }
};

