class Solution {
    public int subarrayLCM(int[] nums, int k) {
        int n = nums.length, ans = 0;
        for (int i = 0; i < n; i++) {
            TreeMap<Integer, Long> vals = new TreeMap<>();
            for (int j = i; j < n; j++) {
                int x = nums[j];
                if (k % x != 0) break;
                TreeMap<Integer, Long> nxt = new TreeMap<>();
                nxt.merge(x, 1L, Long::sum);
                for (var e : vals.entrySet()) {
                    int nv = e.getKey() / gcd(e.getKey(), x) * x;
                    if (k % nv == 0) nxt.merge(nv, e.getValue(), Long::sum);
                }
                vals = nxt;
                ans += vals.getOrDefault(k, 0L);
            }
        }
        return ans;
    }
    private int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
}

